/// Lesson sections for the info page — never shown on the practice screen.
const List<TechniqueSection> setFillFlamsLesson = [
  TechniqueSection(
    title: "Why it matters",
    body:
        "Flams on the toms are the biggest sound a fill can make with slow hands. The pad sheet \"Flam Fill\" taught the fat single note; here each flam lands on a drum, and on 1 and 3 together with the kick.",
  ),
  TechniqueSection(
    title: "How to play it",
    body:
        "Rock eighths for three bars, crash on the one of bar 1. Line 1 plays four flammed quarters: snare, snare, high tom, floor tom. Grace note low and just ahead on the same drum as the main note, main note full height, the kick on 1 and 3 in unison with the flams.",
  ),
  TechniqueSection(
    title: "Practice tips",
    body:
        "Line 2 puts a flam on every beat on a new drum, snare down to floor tom. Line 5 runs sixteenths on the snare and answers with one accented flam on the floor tom on 4. Line 6 is the pataflafla split over snare, high tom, snare and floor tom; line 7 places the syncopated flams on all four toms with rests between. Every flam must still sound like one note when the drum changes. Toms accept any tom and the crash any crash, so a kit with fewer drums plays the sheet too: the mid tom and the second floor tom go to the nearest tom you have.",
  ),
  TechniqueSection(
    title: "Where you hear it",
    body:
        "John Bonham's flammed tom fills, the big single hits before a chorus in rock and metal, marching drum lines.",
  ),
];
